function procesa_video_registro($local_id,$nombre_persona,$nombre_fichero,$ruta){

    $threads=[];

    $nombreunico=shell_exec("php ws.php nombreunico");
    $randaux=rand(1000000,9999999);

    
    //divido el video en muchos videos de {longitus_video} duracion
    $numero_videos=dividir_video2($local_id,$ruta,$nombre_fichero);

    echo "videos divididos:".$numero_videos."\n";
    

    //saca todas la caras posible a motor/caras/sinclasificar_videos/  
    echo "Videos:\n\n";
    for($i=1;$i<=$numero_videos;$i++){
        echo $ruta.$nombre_fichero."_".$i.".avi \n";
        $id="vr_".$i."_".$local_id."_".$randaux;


        $cmd="python3.7 motor/procesa_video_registro_1.py ".$local_id." ".$nombre_fichero."_".$i.".avi ".$i." '".RUTA_PROYECTO."'";
        echo "Alta hilo->".$cmd."\n";
        $threads[$id]=new Jos_Thread($id,$cmd,true);

        $threads[$id]->start();    
    }


    $sigue=true;
    while($sigue){
        $terminados=0;
        for($i=1;$i<=$numero_videos;$i++){
            $id="vr_".$i."_".$local_id."_".$randaux;
            if(!$threads[$id]->isrunning()){
                $terminados++;
                exec("rm libs/threads_files_aux/aux_".$id.".txt");

            }
        }
        if($terminados==$numero_videos){
            $sigue=false;
        }else{
            usleep(500);
        }
    }
    
    
    

    for($i=1;$i<=16;$i++){
        $id="vr_".$i."_".$local_id."_".$randaux;
        $cmd="python3.7 motor/procesa_video_registro_2.py ".$local_id." ".$i." ".$nombreunico." '".RUTA_PROYECTO."'";
        echo "Alta hilo->".$cmd."\n";
        $threads[$id]=new Jos_Thread($id,$cmd,true);

        $threads[$id]->start();  
    }

    $sigue=true;
    while($sigue){
        $terminados=0;
        for($i=1;$i<=16;$i++){
            $id="vr_".$i."_".$local_id."_".$randaux;
            if(!$threads[$id]->isrunning()){
                $terminados++;
                exec("rm libs/threads_files_aux/aux_".$id.".txt");
            }
        }
        if($terminados==16){
            $sigue=false;
        }else{
            usleep(500);
        }
    }


    echo "\n\n\n";
    echo "RESULTADOS\n";

    $IMAGENES_TOTAL=0;
    $IMAGENES_DESENFOCADAS=0;
    $IMAGENES_NOSEPUEDERECORTARCARA=0;
    $IMAGENES_CONCARA=0;

    for($i=1;$i<=16;$i++){
        $file='aux/procesa_video_registro_resultado_'.$local_id.'_'.$i.'.txt';
        $res=file_get_contents($file);
        echo "Para el hilo:".$i.", los resultados son:".$res."\n";
        exec("rm ".$file);

        $vres= explode(";;", $res);

        $IMAGENES_TOTAL+=((int)(trim($vres[0])));
        $IMAGENES_DESENFOCADAS+=((int)(trim($vres[1])));
        $IMAGENES_NOSEPUEDERECORTARCARA+=((int)(trim($vres[2])));
        $IMAGENES_CONCARA+=((int)(trim($vres[3])));

        $ganador_name=$vres[4];
        $fotos_identificadorunico=$vres[5];




    }
    echo "\n\n\n";
    echo "TOTALES\n";

    echo "IMAGENES_TOTAL:".$IMAGENES_TOTAL."\n";
    echo "IMAGENES_DESENFOCADAS:".$IMAGENES_DESENFOCADAS."\n";
    echo "IMAGENES_NOSEPUEDERECORTARCARA:".$IMAGENES_NOSEPUEDERECORTARCARA."\n";
    echo "IMAGENES_CONCARA:".$IMAGENES_CONCARA."\n";
    
    echo "ganador_name:".$ganador_name."\n";
    echo "fotos_identificadorunico:".$fotos_identificadorunico."\n";
    

    echo "\n\n\n";

    echo "CONCLUSIONES:\n";

    $correcto=true;



    //si hay muchas desenfocadas da mas luz                                   20%
    if(($IMAGENES_TOTAL*$IMAGENES_DESENFOCADAS/100)>=20){
        $correcto=true;
        echo "hay muchas desenfocadas da mas luz\n";
    }

    //si hay muchas que no se puede recortar, exate parta atras un poco       20%
    if(($IMAGENES_TOTAL*$IMAGENES_NOSEPUEDERECORTARCARA/100)>=20){
        $correcto=true;
        echo "hay muchas que no se puede recortar, exate parta atras un poco\n";
    }

    //si hay pocas imagenes extraidas el video es muy corto o mal grabado     +de 200 imgs buenas o malas
    if($IMAGENES_TOTAL<150){
        $correcto=true;
        echo "hay pocas imagenes extraidas el video es muy corto o mal grabado\n";
    }

    //si hay pocas imagenes con cara no te as colocado bien                   +70%
    if(($IMAGENES_TOTAL*$IMAGENES_CONCARA/100)<=70){
        $correcto=true;
        echo "hay pocas imagenes con cara no te as colocado bien\n";
    }     

    $tiempo_final = microtime(true);
    $tiempo = $tiempo_final - $tiempo_inicial;       
    echo "El tiempo de ejecución del archivo ha sido de " . $tiempo . " segundos";
    
