        $sql->Consultar("personas","*","cod_interno='".$ganador_name."'","id",true);
        if($sql->num>0){
            $sql->Actualizar("personas",["nombre"],[$nombre_persona],true);
            $actualizado=true;
        }else{
            echo "sleep..\n";
            sleep(2);    
        }
    }
}


/*se divide el video original en videos de 4 segundos de duracion*/
function dividir_video($local_id,$ruta,$video){
    
    $salida=$ruta.$video;
    $video=$ruta.$video.".avi";
    
    
    
    $output_salida="aux/procesa_video_registro_".$local_id."_".rand(1000000,9999999).".txt";

    global $longitud_videos;
    
    $time=0;
    $i=1;
    $terminado=false;
    while(!$terminado){
        $ini_txt="";
        $fin_txt="";
        if($time<10){
            $ini_txt.="0";
        }
        if(($time+$longitud_videos)<10){
            $fin_txt.="0";
        }
        $ini_txt.=$time;
        $fin_txt.=$time+$longitud_videos;
       
        
       
        //ffmpeg -ss 00:00:00 -to 00:00:05  -i /var/www/html/reconocimientoFacial/proyecto_definitivo/admin/files/videos_registro/prueba2.avi -c:v libx264 /var/www/html/reconocimientoFacial/proyecto_definitivo/admin/files/videos_registro/prueba2_2.avi > ./aux/procesa_video_registro_good.txt 2>&1
        $cmd="ffmpeg -i ".$video." -ss 00:00:".$ini_txt." -to 00:00:".$fin_txt." -c:v libx264 ".$salida."_".$i.".avi > ".$output_salida." 2>&1";
        echo "Ejecuto1:".$cmd."\n\n";
        exec($cmd);

        $test= file_get_contents($output_salida);
        if(strpos($test, "nothing was encoded")!==false){
            exec("rm ".$salida."_".$i.".avi");
            $resta=1;
            while(!$terminado){
                $ini_txt="";
                $fin_txt="";
                if($time<10){
                    $ini_txt.="0";
                }
                if(($time+$longitud_videos)<10){
                    $fin_txt.="0";
                }
                $ini_txt.=$time;
                $fin_txt.=$time+5-$resta;        
                $cmd="ffmpeg -ss 00:00:".$ini_txt." -to 00:00:".$fin_txt."  -i ".$video." -c:v libx264 ".$salida."_".$i.".avi > ".$output_salida." 2>&1";
                echo "Ejecuto2:".$cmd."\n\n";
                exec($cmd);
                $test= file_get_contents($output_salida);
                if(strpos($test, "nothing was encoded")===false){
                    $terminado=true;
                }else{
                    exec("rm ".$salida."_".$i.".avi");
                }
                
                $resta++;
                if($resta==$longitud_videos){
                    $terminado=true;
                    $i--;
                }
            }
        }
        
        $time+=$longitud_videos;
        $i++;
        if($time==55){
            $terminado=true;
        }
    }
    exec("rm ".$output_salida);
    
    return ($i-1);
}




/*se divide el video original en videos de 4 segundos de duracion*/
function dividir_video2($local_id,$ruta,$video){
    
    global $longitud_videos;
    
    $salida=$ruta.$video;
    $video=$ruta.$video.".avi";
    $output_salida="aux/procesa_video_registro_".$local_id."_".rand(1000000,9999999).".txt";

    
    $ss=0;
    $mm=0;
    
    $i=1;
    $terminado=false;
    while(!$terminado){

        $ss_ini=$ss;
        if($ss_ini<10){
            $ss_ini="0".$ss_ini;
        }
        $mm_ini=$mm;
        if($mm_ini<10){
            $mm_ini="0".$mm;
        }
        
        $ss_fin=$ss+$longitud_videos;
        $suma_mm=0;
        if($ss_fin>=60){
           $ss_fin=$ss_fin-60; 
           $suma_mm=1;
        }
        $ss_fin_sinretoques=$ss_fin;
        if($ss_fin<10){
            $ss_fin="0".$ss_fin;
        }
        
        
        $mm_fin=$mm+$suma_mm;
        $mm_fin_sinretoques=$mm_fin;
        if($mm_fin<10){
            $mm_fin="0".$mm_fin;
        }
        
        $ss=$ss_fin_sinretoques;
        $mm=$mm_fin_sinretoques;
        
        $ini_txt="00:".$mm_ini.":".$ss_ini;
        $fin_txt="00:".$mm_fin.":".$ss_fin;
        
        
        $cmd="ffmpeg -i ".$video." -ss ".$ini_txt." -to ".$fin_txt." -c:v libx264 ".$salida."_".$i.".avi > ".$output_salida." 2>&1";
        echo "Ejecuto1:".$cmd."\n\n";
        exec($cmd);

        $test= file_get_contents($output_salida);
        if(strpos($test, "nothing was encoded")!==false){   //esto es para los ultimos segundos del video cony
            exec("rm ".$salida."_".$i.".avi");
            
            $resta=1;
            while(!$terminado){
                
                $ss_fin=$ss_fin_sinretoques-$resta;
                $resta_minutos=0;
                if($ss_fin<0){
                    $ss_fin+=60;
                    $resta_minutos=1;
                }
                $ss_fin_sinretoques=$ss_fin;
                
                if($ss_fin<10){
                    $ss_fin="0".$ss_fin;
                }
                
                $mm_fin=$mm_fin_sinretoques-$resta_minutos;
                $mm_fin_sinretoques=$mm_fin;
                if($mm_fin<10){
                    $mm_fin="0".$mm_fin;
                }
                $fin_txt="00:".$mm_fin.":".$ss_fin;
                
                
                $cmd="ffmpeg -ss ".$ini_txt." -to ".$fin_txt."  -i ".$video." -c:v libx264 ".$salida."_".$i.".avi > ".$output_salida." 2>&1";
                echo "Ejecuto2 para los ultimos seg del video:".$cmd."\n\n";
                exec($cmd);
                $test= file_get_contents($output_salida);
                if(strpos($test, "nothing was encoded")===false){
                    $terminado=true;
                }else{
                    exec("rm ".$salida."_".$i.".avi");
                }
                
                $resta++;
                if($resta==$longitud_videos){
                    $terminado=true;
                    $i--;
                }
            }
        }
        $i++;

    }
    exec("rm ".$output_salida);
    exec("rm ".$video);
    
    return ($i-1);
}




